# ------------------------------------------------------------------ helpers for the agent instructions (our words)
FW = {'must': "an obligation ('must')", 'should': "a recommendation ('should')", 'will': "an expected outcome ('will')",
      'threshold': 'a threshold the award requires',
      'tshould': "a threshold expectation, worded 'should be able to'"}
def aw(n, what, beside, noclaim, force):
    return (f"Describe this as {FW[force]}: {what}, set for {LEVEL}. "
            f"Cite it as QAA (2024) Optometry Subject Benchmark Statement, para {n}. "
            f"Do not claim {noclaim}. Set it beside {beside}.")
FR_L = "With a student, use plain words and the second person; with staff, frame it as what the course has to let every graduate show."
FR_P = "Frame it for the programme team or teacher as a duty on the course, in their own planning terms."
def ad(when, ask, avoid, frame=FR_L):
    return f"Raise this when {when}. {frame} Ask: {ask} Avoid reading the issuer's paragraph aloud and avoid {avoid}."
NOT_REG = "that the statement itself is a regulatory requirement, or that it covers non-registrable vision science awards"
NOT_GOC = "that this summary is the General Optical Council's own wording or that it replaces the GOC requirements, nor that it holds at Level 6"
DUTY = "putting it to a student as something they must achieve, since it is a duty on the course"

